for _ in range(int(input())):
	(a, b) = map(str, input().split())
	lst = {}
	flag = 0
	for i in range(len(a)):
		if a[i] in lst:
			lst[a[i]] += 1
		else:
			lst[a[i]] = 1
	for i in range(len(b)):
		if b[i] in lst:
			lst[b[i]] += 1
		else:
			lst[b[i]] = 1
	for j in range(int(input())):
		son = input()
		for k in range(len(son)):
			if son[k] in lst and lst[son[k]] >= 1:
				lst[son[k]] -= 1
			else:
				flag = 1
				break
	if flag == 0:
		print('YES')
	else:
		print('NO')
